<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {mutate,PLANNING_PREVIEW_TIMEOUT_MS} from '../api'
import {explorationApi,isMultiDayItinerary,type EnginePreview,type PlanningObjective} from '../explorationApi'
import {clone,clock,journey,loadJourney,loadConfirmedRoute,localDate,nameOf,notify} from '../journey'
import {memoryEpoch} from '../voiceDraft'
import PlanPreview from './PlanPreview.vue'
interface Day{day_id:string;business_date:string;starts_at:string;ends_at:string;origin_place_id:string|null;destination_place_id:string|null;pace?:string;objective?:PlanningObjective;modes?:string[]}
interface Goal{goal_id:string;target_kind:string;target_id:string;required:boolean;duration_seconds:number|null;allowed_dates:string[];fixed_date:string|null;kind?:string}
interface Requirements extends Record<string,unknown>{days:Day[];goals:Goal[];overnights:{from_day_id:string;to_day_id:string;place_id:string}[]}
const props=defineProps<{dayId:string}>()
const busy=ref(false),open=ref(false),error=ref(''),working=ref<Requirements>(),order=ref<string[]>([]),removed=ref<string[]>([]),selectedPlace=ref(''),preview=ref<EnginePreview>(),selected=ref(0)
let generation=0,disposed=false
const day=computed(()=>working.value?.days.find(d=>d.day_id===props.dayId))
const original=computed(()=>journey.route?.requirements as Requirements|undefined)
const eligible=computed(()=>{const p=journey.route?.itinerary;if(!p||!isMultiDayItinerary(p)||!journey.trip||!['DRAFT','ACTIVE','PAUSED'].includes(journey.trip.status))return false;const d=p.days.find(d=>d.day_id===props.dayId);return !!d&&d.business_date>localDate()&&d.status==='pending'&&!d.itinerary.ongoing&&!d.itinerary.completed_prefix?.length})
const goals=computed(()=>order.value.flatMap(id=>working.value?.goals.filter(g=>g.goal_id===id)||[]))
const places=computed(()=>journey.catalog.filter(p=>p.record.kind==='place'))
const label=(g:Goal)=>journey.catalog.find(p=>p.record.fact_id===g.target_id)?.record.name||g.target_id
const dirty=()=>{generation++;preview.value=undefined;error.value=''}
function reset(){generation++;open.value=false;working.value=undefined;order.value=[];removed.value=[];preview.value=undefined;error.value='';busy.value=false}
watch(()=>[props.dayId,journey.trip?.id,journey.trip?.version,journey.route?.version,memoryEpoch.value],reset)
onBeforeUnmount(()=>{disposed=true;generation++})
function edit(){reset();if(!original.value||!journey.route?.itinerary||!isMultiDayItinerary(journey.route.itinerary))return;working.value=clone(original.value);const plan=journey.route.itinerary;const other=new Set(plan.days.filter(d=>d.day_id!==props.dayId).flatMap(d=>[...d.requirements.goals.map(g=>g.goal_id),...(d.itinerary.completed_prefix||[]).map(s=>s.stop_id),...(d.itinerary.ongoing?[d.itinerary.ongoing.stop_id]:[])]));const selected=plan.days.find(d=>d.day_id===props.dayId)!;Object.assign(day.value!,{pace:day.value!.pace||selected.requirements.pace,objective:day.value!.objective||selected.requirements.objective,modes:day.value!.modes||clone(selected.requirements.modes)});const date=day.value!.business_date;const available=working.value.goals.filter(g=>!other.has(g.goal_id)&&g.allowed_dates.includes(date)&&(!g.fixed_date||g.fixed_date===date));const scheduled=plan.days.find(d=>d.day_id===props.dayId)!.itinerary.activities.map(a=>a.goal_id);order.value=[...scheduled,...available.map(g=>g.goal_id).filter(id=>!scheduled.includes(id))];selectedPlace.value='';open.value=true}
function move(index:number,delta:number){const next=index+delta;if(next<0||next>=order.value.length)return;dirty();const id=order.value.splice(index,1)[0];order.value.splice(next,0,id)}
function remove(g:Goal){if(g.required&&removed.value.length){error.value='请先逐项确认取消必去目标';return}dirty();if(g.required)removed.value.push(g.goal_id);working.value!.goals=working.value!.goals.filter(x=>x.goal_id!==g.goal_id);order.value=order.value.filter(id=>id!==g.goal_id)}
function add(){if(!selectedPlace.value||!day.value)return;dirty();const id='future:'+crypto.randomUUID();working.value!.goals.push({goal_id:id,target_kind:'place',target_id:selectedPlace.value,required:false,duration_seconds:1800,allowed_dates:[day.value.business_date],fixed_date:day.value.business_date,kind:places.value.find(p=>p.record.fact_id===selectedPlace.value)?.record.place_type==='restaurant'?'dining':'visit'});order.value.push(id);selectedPlace.value=''}
function time(field:'starts_at'|'ends_at',value:string){if(!day.value)return;dirty();day.value[field]=day.value.business_date+'T'+value+':00+08:00'}
async function calculate(){if(busy.value||!working.value||!day.value||!journey.trip)return;dirty();const token=generation,id=journey.trip.id,version=journey.trip.version;busy.value=true;try{if(day.value.ends_at<=day.value.starts_at)throw new Error('结束时间需要晚于开始时间');const result=await mutate<EnginePreview>(`/city/v1/trips/${id}/engine/replan-preview`,{expected_version:version,requirements:clone(working.value),scope:'selected_future_day',day_id:props.dayId,fixed_goal_ids:order.value,skipped_goal_ids:removed.value},'POST',PLANNING_PREVIEW_TIMEOUT_MS);if(disposed||generation!==token)return;if(!result.candidate_id)throw new Error(result.result?.issues?.map(i=>i.message).join('；')||'当前条件未产生可确认方案，请调整时间或目标');preview.value=result;selected.value=0}catch(e){if(!disposed&&generation===token)error.value=(e as Error).message}finally{if(!disposed&&generation===token)busy.value=false}}
async function confirm(){if(busy.value||!preview.value||!journey.trip)return;const token=generation,id=journey.trip.id,p=preview.value;busy.value=true;error.value='';try{await explorationApi.confirm(id,p.base_version,p.candidate_id!,selected.value);if(disposed||generation!==token)return;reset();await loadJourney(true);await loadConfirmedRoute();notify('已更新所选日期的安排')}catch(e){if(!disposed&&generation===token)error.value=(e as Error).message}finally{if(!disposed&&generation===token)busy.value=false}}
</script>
<template><section v-if="eligible" class="future-planning" aria-label="未来单日调整"><button v-if="!open" type="button" class="button secondary" @click="edit">调整这一天</button><template v-else-if="day"><h3>调整 {{day.business_date}}</h3><p>仅更新这一天。核对整套方案后确认生效。</p><form @submit.prevent="calculate"><fieldset :disabled="busy" @input="dirty" @change="dirty"><div class="future-fields"><label>开始时间<input type="time" :value="clock(day.starts_at)" required @input="time('starts_at',($event.target as HTMLInputElement).value)"></label><label>结束时间<input type="time" :value="clock(day.ends_at)" required @input="time('ends_at',($event.target as HTMLInputElement).value)"></label><label>游玩节奏<select v-model="day.pace"><option value="relaxed">轻松</option><option value="standard">适中</option><option value="compact">紧凑</option></select></label><label>安排偏好<select v-model="day.objective"><option value="balanced">均衡</option><option value="less_walking">少走路</option><option value="less_waiting">少等待</option><option value="lower_cost">省钱</option></select></label></div><label v-for="side in (['origin','destination'] as const)" :key="side">{{side==='origin'?'出发地点':'结束地点'}}<select v-model="day[side==='origin'?'origin_place_id':'destination_place_id']" :disabled="working!.overnights.some(o=>side==='origin'?o.to_day_id===dayId:o.from_day_id===dayId)"><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}</option></select></label><p>相邻日期共用的过夜地点保持原选择。</p><div class="future-modes">交通方式<label v-for="m in [{id:'walking',name:'步行'},{id:'transit',name:'公交'},{id:'driving',name:'打车 / 自驾'}]" :key="m.id"><input v-model="day.modes" type="checkbox" :value="m.id">{{m.name}}</label></div><ol><li v-for="(g,index) in goals" :key="g.goal_id"><strong>{{label(g)}}</strong><small v-if="g.required"> · 必去</small><label v-if="g.target_kind!=='session'">停留分钟<input type="number" min="1" max="360" :value="g.duration_seconds?g.duration_seconds/60:''" @input="g.duration_seconds=Number(($event.target as HTMLInputElement).value)*60||null"></label><div class="goal-tools"><button type="button" :disabled="index===0" :aria-label="'上移：'+label(g)" @click="move(index,-1)">上移</button><button type="button" :disabled="index===goals.length-1" :aria-label="'下移：'+label(g)" @click="move(index,1)">下移</button><button type="button" @click="remove(g)">{{g.required?'取消必去：':'移除：'}}{{label(g)}}</button></div></li></ol><p v-if="removed.length" role="status">本次明确取消 {{removed.length}} 个必去目标，请核对预览中的移除项。</p><label>添加地点<select v-model="selectedPlace"><option value="">请选择</option><option v-for="p in places" :key="p.record.fact_id" :value="p.record.fact_id">{{p.record.name}}</option></select></label><button type="button" :disabled="!selectedPlace" @click="add">添加到这一天</button><button type="submit" class="button primary">预览这一天的调整</button></fieldset></form><p v-if="busy" role="status">正在处理…</p><p v-if="error" role="alert">{{error}}</p><template v-if="preview"><PlanPreview :plans="preview.result.itineraries" :selected="selected" :disabled="busy" :changes="preview.alternative_changes?.[selected]" @select="selected=$event"/><button type="button" class="button primary" :disabled="busy" @click="confirm">确认更新这一天</button></template><button type="button" :disabled="busy" @click="reset">保留原安排</button></template></section></template>
<style scoped>.future-planning{margin:16px 0;padding:14px;border:1px solid #ded4c2;border-radius:10px;font-size:13px;line-height:1.8}.future-planning fieldset{border:0;padding:0;display:grid;gap:12px}.future-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.future-planning select,.future-planning input:not([type=checkbox]){display:block;width:100%;min-height:44px;box-sizing:border-box}.future-planning button{min-height:44px;padding:8px}.future-modes label{display:inline-flex;margin-right:10px}.future-planning ol{padding-left:20px}.future-planning li{padding:10px 0}.goal-tools{display:flex;flex-wrap:wrap;gap:8px}</style>
